import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`fencing-estimate`,heroTitle:`Turn plans into fencing estimates in minutes`,heroSubtitle:`Perplexity Computer analyzes your uploaded plans and site notes, sizes fencing materials and labor, and drafts a detailed estimate automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your fencing plans`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded fencing plans, property measurements, or site photos. Build a complete fencing estimate. (1) Extract linear footage, fence type, gates, posts, footings, demolition scope, terrain constraints, and access issues from the uploaded files. (2) Estimate materials, concrete, hardware, labor, equipment, and hauling needs. (3) Build pricing options with assumptions, alternates, and margin. (4) Highlight exclusions, permit questions, and field-verification items that should be confirmed before sending. (5) Deliver a detailed fencing estimate with line-item pricing, scope summary, and next steps that is ready for the customer.`,heroOverlaySteps:[`Extracting linear footage, fence type, gates, and terrain constraints from your files`,`Sizing materials, concrete, labor, equipment, and hauling needs`,`Building pricing options with assumptions, alternates, and margin`,`Customer-ready fencing estimate with scope summary, ready to send`],generatingSteps:[`Reading the uploaded plans, measurements, and site photos`,`Designing an agent to organize material counts and installation assumptions`,`Configuring estimate logic for alternates, permit questions, and margin`,`Preparing a detailed fencing estimate with line items and next steps`],featureSectionTitle:`From site plan to estimate-ready pricing`,featureCardTitles:[`Connects to your estimating workflow`,`Estimates built around real site conditions`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Docs, sheets, measurements, and internal review workflows stay connected so quoting and revisions move faster.`,`Material counts. Gate options. Labor assumptions. Site constraints. Computer gives your team a fencing estimate draft that is ready for customer review.`],capabilitySectionTitle:`Your estimator, on autopilot`,capabilitySectionSubtitle:`Upload the plans, get back a fencing estimate built around the real site scope.`,capabilityCards:[{title:`Plan & Site Analysis`,description:`Computer can extract linear footage, fence type, gate count, terrain issues, and installation constraints from plans, notes, and photos.`},{title:`Materials & Labor Planning`,description:`Computer can size posts, panels, concrete, hardware, labor, and hauling so the estimate reflects the actual site conditions.`},{title:`Pricing Options`,description:`Computer can build pricing with assumptions, alternates, and margin so you can send a clearer estimate with less spreadsheet work.`},{title:`Connect Your Tools`,description:`Computer can organize estimate drafts across docs, sheets, and internal workflows so review and handoff are easy for your team.`},{title:`Knows Your Standards`,description:`Computer can remember your preferred materials, pricing guardrails, and estimate structure across sessions so every quote stays consistent.`},{title:`Revision Support`,description:`Computer can update the estimate when the layout, gate count, or site conditions change after the first draft.`}]});export{t as default};
